// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsFile 是每个仓库的阈值配置文件，属于仓库根目录下的 config/。
const thresholdsFile = "thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 仓库配置在 config/thresholds.json 里；没配、文件读不到或不是 JSON 对象时
// 回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := readThresholds()[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// readThresholds 读取 config/thresholds.json。任何读不出来的情况都返回 nil，
// 让调用方回退到默认值。
func readThresholds() map[string]int {
	path, ok := findThresholdsFile()
	if !ok {
		return nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	thresholds := map[string]int{}
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// findThresholdsFile 从当前工作目录往上找 config/thresholds.json，
// 这样不管测试在包目录还是仓库根目录运行都能找到。
func findThresholdsFile() (string, bool) {
	dir, err := os.Getwd()
	if err != nil {
		return "", false
	}
	for {
		candidate := filepath.Join(dir, "config", thresholdsFile)
		if info, err := os.Stat(candidate); err == nil && !info.IsDir() {
			return candidate, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}
```

