func TestScratchConfigSource(t *testing.T) {
	path := filepath.Join("..", "config", "thresholds.json")
	t.Cleanup(func() { _ = os.Remove(path) })

	write := func(content string) {
		t.Helper()
		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
	}

	// configured warehouse uses its own threshold, others fall back
	write(`{"tokyo": 12}`)
	if got := LowStockThreshold("tokyo"); got != 12 {
		t.Fatalf("tokyo = %d, want 12", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("chengdu = %d, want default", got)
	}

	// invalid JSON -> fallback
	write(`not json`)
	if got := LowStockThreshold("tokyo"); got != DefaultLowStockThreshold {
		t.Fatalf("invalid json tokyo = %d, want default", got)
	}

	// non-object JSON -> fallback
	write(`[1,2,3]`)
	if got := LowStockThreshold("tokyo"); got != DefaultLowStockThreshold {
		t.Fatalf("array tokyo = %d, want default", got)
	}

	// missing file -> fallback
	if err := os.Remove(path); err != nil {
		t.Fatal(err)
	}
	if got := LowStockThreshold("tokyo"); got != DefaultLowStockThreshold {
		t.Fatalf("missing file tokyo = %d, want default", got)
	}
}

