	for i, w := range ws {
		if got[i] != w+"="+itoa(stock[w]) {
			t.Fatalf("order mismatch at %d: %q vs %q", i, got[i], w)
		}
	}
	if r := LowStockReport(map[string]int{}); len(r) != 0 {
		t.Fatalf("empty report = %v", r)
	}
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var b []byte
	for n > 0 {
		b = append([]byte{byte('0' + n%10)}, b...)
		n /= 10
	}
	if neg {
		b = append([]byte{'-'}, b...)
	}
	return string(b)
}
